/* #zap command, 'z' (or 'y' if numbed_pad==-1) */
/** C ref: zap.c:2627 @returns {CInt} */
export function* dozap() {
    let obj;
    let damage;
    let need_dir;

    if (((cptr.ldU64o(
        (cptr.ldPtro(gy, $instance_globals_y_youmonst + $monst_data)),
        $permonst_mflags1
    ) &
            8192n) != 0n)) {
        (yield* You(__s_aren_t_able_to_zap_anything_in_your));
        return NHM.ECMD_OK;
    }
    if ((yield* check_capacity(null)))
        return NHM.ECMD_OK;
    obj = (yield* getobj(__s_zap, zap_ok, NHM.GETOBJ_NOFLAGS));
    if (!obj)
        return NHM.ECMD_CANCEL;

    (yield* check_unpaid(obj));

    need_dir = ((cptr.ldI32o2(
        objects,
        cptr.ldI16o(obj, $obj_otyp),
        $sizeof_objclass,
        $objclass_oc_dir
    ) & 7) | 0) !=
            NHM.NODIR;
    if (!(yield* zappable(obj))) {
        (yield* pline(__s_pct_s, cptr.ldPtr(c_common_strings)));
    } else if ((cptr.ldI32o(obj, $obj_cursed) & 1) | 0 && !rn2(NHM.WAND_BACKFIRE_CHANCE)) {
        (yield* backfire(obj));  /* the wand blows up in your face! */
        (yield* exercise(NHC.A_STR, 0));
        /* 'obj' is gone; skip update_inventory() because
           backfire() -> useupall() -> freeinv() did it */
        return NHM.ECMD_TIME;
    } else if (need_dir && !(yield* getdir(null))) {
        if (!Blind())
            (yield* pline(__s_s_glows_and_fades, (yield* The((yield* xname(obj))))));
        /* make him pay for knowing !NODIR */
    } else if (need_dir &&
            !cptr.ldI32o(u, $you_dx) &&
            !cptr.ldI32o(u, $you_dy) &&
            !cptr.ldI32o(u, $you_dz)) {
        if ((damage = (yield* zapyourself(obj, 1))) != 0) {
            let buf = new Uint8Array(256);

            void cptr.sprintf(
                cptr.decay(buf),
                __s_zapped_sself_with_s,
                (cptr.ldPtro2(
                    genders,
                    cptr.ld1so(flags, $flag_female) ? 1 : 0,
                    $sizeof_Gender,
                    $Gender_him
                )),
                (yield* killer_xname(obj))
            );
            (yield* losehp(
                ((Half_physical_damage()) ? (((((damage) + 1) | 0) / 2) | 0) : (damage)),
                cptr.decay(buf),
                NHM.NO_KILLER_PREFIX
            ));
        }
    } else {
        /*      Are we having fun yet?
         * weffects -> buzz(obj->otyp) -> zhitm (temple priest) ->
         * attack -> hitum -> known_hitum -> ghod_hitsu ->
         * buzz(AD_ELEC) -> destroy_items(AD_ELEC) ->
         * useup -> obfree -> dealloc_obj -> free(obj)
         */
        cptr.stPtro(gc, $instance_globals_c_current_wand, obj);
        (yield* weffects(obj));
        obj = cptr.ldPtro(gc, $instance_globals_c_current_wand);
        cptr.stPtro(gc, $instance_globals_c_current_wand, null);
    }
    if (obj && cptr.ld1so(obj, $obj_spe) < 0) {
        (yield* pline(__s_s_to_dust, (yield* Tobjnam(obj, __s_turn))));
        (yield* useupall(obj));  /* calls freeinv() -> update_inventory() */
    } else
        (yield* update_inventory());  /* maybe used a charge */
    return NHM.ECMD_TIME;
}

/* Lock or unlock all boxes in inventory */
/** C ref: zap.c:2687 — @param {CPtr<struct obj>} obj */
function* boxlock_invent(obj) {
    let otmp;
    let nextobj;
    let boxing = 0;

    /* (un)lock carried boxes */
    for (otmp = cptr.ldPtro(gi, $instance_globals_i_invent); otmp; otmp = nextobj) {
        nextobj = cptr.ldPtr(otmp);
        if (Is_box(otmp)) {
            void (yield* boxlock(otmp, obj));
            boxing = 1;
        }
    }
    if (boxing)
        (yield* update_inventory());  /* in case any box->lknown has changed */
}

